// The module 'vscode' contains the VS Code extensibility API
// Import the module and reference it with the alias vscode in your code below
const vscode = require('vscode');

/* ----------------------------------------------------------- */

const EXTENSION_NAME = 'dotodos';
const LANG_ID = 'dotodos';

/**
 * Icons made out of characters
 */
const charcons = {
	task: {
		done: '☑',
		todo: '☐'
	},
};

const SECTION_LINE_PATTERN = /^(.+):\s*(?:\((?:\d+|\d+\/\d+)\)(?:\s*\|\s*\d+%)?)?$/;

function getDotodoEditorOrErrorMessage() {
	const activeEditor = vscode.window.activeTextEditor;

	if (!activeEditor || activeEditor.document.languageId !== LANG_ID) {
		vscode.window.showErrorMessage(`Please open a .${LANG_ID} file first`);
		return false;
	}

	return activeEditor;
}

/* ----------------------------------------------------------- */

function registerDecorations(context) {
    // Cache for task content lines to avoid recalculating
    let taskContentCache = new Map(); // key: documentUri_lineNumber, value: array of content line numbers
    let documentVersion = -1;

    // decoration for todo checkbox only
    const todoDecoration = vscode.window.createTextEditorDecorationType({
        color: new vscode.ThemeColor('editorLineNumber.foreground'),
        fontWeight: 'bold'
    });

    // decoration for done checkbox only
    const doneCheckboxDecoration = vscode.window.createTextEditorDecorationType({
        color: new vscode.ThemeColor('editorLineNumber.foreground'),
        fontWeight: 'bold'
    });

    // decoration for done task text (with strikethrough)
    const doneDecoration = vscode.window.createTextEditorDecorationType({
        color: new vscode.ThemeColor('editorLineNumber.foreground'),
        textDecoration: 'line-through'
    });

    // decoration for timestamp on done tasks
    const timestampDecoration = vscode.window.createTextEditorDecorationType({
        after: {
            color: new vscode.ThemeColor('editorHint.foreground'),
            fontStyle: 'italic',
            margin: '0 0 0 0.5em'
        }
    });

    // decoration for sections (bold and themed color)
    const sectionDecoration = vscode.window.createTextEditorDecorationType({
        color: new vscode.ThemeColor('editorInfo.foreground'),
        fontWeight: 'bold'
    });

    // decoration for section counters (displayed after section text)
    const counterDecoration = vscode.window.createTextEditorDecorationType({
        after: {
            color: new vscode.ThemeColor('editorHint.foreground'),
            fontStyle: 'normal',
            fontWeight: 'normal'
        }
    });

    // keep disposables so they get cleaned up
    context.subscriptions.push(todoDecoration, doneCheckboxDecoration, doneDecoration, sectionDecoration, counterDecoration, timestampDecoration);

    // Clear cache when document version changes
    function clearCacheIfNeeded(doc) {
        if (doc.version !== documentVersion) {
            taskContentCache.clear();
            documentVersion = doc.version;
        }
    }

    function updateDecorations(editor) {
        editor = editor || vscode.window.activeTextEditor;

        if (!editor || editor.document.languageId !== LANG_ID) {
            return;
        }

        clearCacheIfNeeded(editor.document);

        const todoRanges = [];
        const doneCheckboxRanges = [];
        const doneRanges = [];
        const sectionRanges = [];
        const counterRanges = [];
        const timestampRanges = [];

        for (let i = 0; i < editor.document.lineCount; i++) {
            const line = editor.document.lineAt(i);
            const trimmed = line.text.trim();

            if (trimmed.startsWith(charcons.task.todo)) {
                // Only decorate the checkbox character, not the entire line
                const checkboxStart = new vscode.Position(i, line.firstNonWhitespaceCharacterIndex);
                const checkboxEnd = new vscode.Position(i, line.firstNonWhitespaceCharacterIndex + 1);
                todoRanges.push(new vscode.Range(checkboxStart, checkboxEnd));
            } else if (trimmed.startsWith(charcons.task.done)) {
                // For done tasks, apply strikethrough only to non-whitespace runs
                // Skip the checkbox character and the timestamp at the end
                const checkboxStart = new vscode.Position(i, line.firstNonWhitespaceCharacterIndex);
                const checkboxEnd = line.firstNonWhitespaceCharacterIndex + charcons.task.done.length;
                doneCheckboxRanges.push(new vscode.Range(checkboxStart, new vscode.Position(i, checkboxEnd)));
                const timestampMatch = line.text.match(/ @\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
                const textEnd = timestampMatch ? timestampMatch.index : line.text.length;
                getNonWhitespaceRanges(line, i, doneRanges, checkboxEnd, textEnd);

                // Also apply strikethrough to task content lines
                const contentLines = getTaskContentLines(editor.document, i);
                for (const contentLineNum of contentLines) {
                    const contentLine = editor.document.lineAt(contentLineNum);
                    if (contentLine.text.trim() !== '') {
                        getNonWhitespaceRanges(contentLine, contentLineNum, doneRanges);
                    }
                }
            } else if (isSectionLine(line.text)) {
                // Section header - detect sections with or without counters
                const sectionName = extractSectionName(trimmed);
                const start = new vscode.Position(i, line.firstNonWhitespaceCharacterIndex);
                const end = new vscode.Position(i, line.text.length);
                sectionRanges.push(new vscode.Range(start, end));

                // Add counter decoration
                const { doneCount, allCount } = countTasksInSection(editor.document, i);
                const counterText = formatCounterText(sectionName, doneCount, allCount);

                counterRanges.push({
                    range: new vscode.Range(i, line.text.length, i, line.text.length),
                    renderOptions: { after: { contentText: counterText } }
                });
            }
        }

        editor.setDecorations(todoDecoration, todoRanges);
        editor.setDecorations(doneCheckboxDecoration, doneCheckboxRanges);
        editor.setDecorations(doneDecoration, doneRanges);
        editor.setDecorations(sectionDecoration, sectionRanges);
        editor.setDecorations(counterDecoration, counterRanges);
        editor.setDecorations(timestampDecoration, timestampRanges);
    }

    // Helper functions for section detection and counting
    function isSectionLine(lineText) {
        const trimmed = lineText.trim();
        if (!trimmed) return false;
        if (isTaskLine(trimmed)) return false;
        return SECTION_LINE_PATTERN.test(trimmed);
    }

    function extractSectionName(trimmed) {
        const match = trimmed.match(SECTION_LINE_PATTERN);
        return match ? match[1].trim() : trimmed;
    }

    function isTaskLine(trimmed) {
        return trimmed.startsWith(charcons.task.todo) || trimmed.startsWith(charcons.task.done);
    }

    function formatCounterText(sectionName, doneCount, allCount) {
        const percent = allCount === 0 ? 0 : Math.round((doneCount / allCount) * 100);

        if (sectionName === 'Archived') {
            return ` (${allCount}) | ${percent}%`;
        }

        return ` (${doneCount}/${allCount}) | ${percent}%`;
    }

    /**
     * Get the content lines that belong to a task.
     * Content is any text between the task and the next task/section.
     * Returns array of line numbers that are content for the given task line.
     * Uses caching to avoid recalculating for the same task.
     */
    function getTaskContentLines(doc, taskLineNum) {
        const cacheKey = `${doc.uri.toString()}_${taskLineNum}`;
        
        // Check cache first
        if (taskContentCache.has(cacheKey)) {
            return taskContentCache.get(cacheKey);
        }

        const contentLines = [];
        const taskLine = doc.lineAt(taskLineNum);
        const taskIndent = taskLine.text.substring(0, taskLine.firstNonWhitespaceCharacterIndex).length;

        // Look at lines below the task
        for (let i = taskLineNum + 1; i < doc.lineCount; i++) {
            const line = doc.lineAt(i);
            const trimmed = line.text.trim();
            const lineIndent = line.text.substring(0, line.firstNonWhitespaceCharacterIndex).length;

            // Empty lines are part of content
            if (trimmed === '') {
                contentLines.push(i);
                continue;
            }

            // If we hit another task at same or less indentation, stop
            if (isTaskLine(trimmed) && lineIndent <= taskIndent) {
                break;
            }

            // If we hit a section, stop
            if (isSectionLine(line.text)) {
                break;
            }

            // If we hit a task at deeper indentation, it's a subtask, not content - stop
            if (isTaskLine(trimmed) && lineIndent > taskIndent) {
                break;
            }

            // Otherwise, this line is content
            contentLines.push(i);
        }

        // Cache the result
        taskContentCache.set(cacheKey, contentLines);
        return contentLines;
    }

    /**
     * Pushes ranges covering only non-whitespace character runs on a line.
     * This ensures strikethrough decoration doesn't bleed through tabs/spaces.
     * @param {vscode.TextLine} line - The text line to process
     * @param {number} lineNum - The line number
     * @param {vscode.Range[]} ranges - Array to push ranges into
     * @param {number} [startCol] - Optional start column (defaults to first non-whitespace)
     * @param {number} [endCol] - Optional end column (defaults to line length)
     */
    function getNonWhitespaceRanges(line, lineNum, ranges, startCol, endCol) {
        const text = line.text;
        let i = startCol !== undefined ? startCol : line.firstNonWhitespaceCharacterIndex;
        const end = endCol !== undefined ? endCol : text.length;
        while (i < end) {
            // Skip whitespace
            if (text[i] === ' ' || text[i] === '\t') {
                i++;
                continue;
            }
            // Start of a non-whitespace run
            const start = i;
            while (i < end && text[i] !== ' ' && text[i] !== '\t') {
                i++;
            }
            ranges.push(new vscode.Range(lineNum, start, lineNum, i));
        }
    }

    function countTasksInSection(doc, sectionLine) {
        let doneCount = 0;
        let todoCount = 0;
        const sectionIndent = doc.lineAt(sectionLine).firstNonWhitespaceCharacterIndex;
        
        // Find the next section at the same or higher level, or the end of document.
        let nextSectionLine = doc.lineCount;
        for (let i = sectionLine + 1; i < doc.lineCount; i++) {
            const line = doc.lineAt(i);
            if (isSectionLine(line.text) && line.firstNonWhitespaceCharacterIndex <= sectionIndent) {
                nextSectionLine = i;
                break;
            }
        }

        // Count tasks between this section and next section
        for (let i = sectionLine + 1; i < nextSectionLine; i++) {
            const line = doc.lineAt(i);
            const trimmed = line.text.trim();
            if (trimmed.startsWith(charcons.task.done)) {
                doneCount++;
            } else if (trimmed.startsWith(charcons.task.todo)) {
                todoCount++;
            }
        }

        return { doneCount, todoCount, allCount: doneCount + todoCount };
    }

    // update when active editor changes
    context.subscriptions.push(vscode.window.onDidChangeActiveTextEditor(editor => {
        updateDecorations(editor);
    }));

    // update when document text changes
    context.subscriptions.push(vscode.workspace.onDidChangeTextDocument(event => {
        const editor = vscode.window.activeTextEditor;
        if (editor && event.document === editor.document && editor.document.languageId === LANG_ID) {
            updateDecorations(editor);
        }
    }));

    // initial run
    updateDecorations();
}

/**
 * This method is called when your extension is activated.
 * Your extension is activated the very first time the command is executed.
 * @param {vscode.ExtensionContext} context
 */
function activate(context) {
	const subscriptions = {
		markAsTask: vscode.commands.registerCommand(`${EXTENSION_NAME}.markAsTask`, function () {
			try {
				const editor = getDotodoEditorOrErrorMessage();

				if (!editor) {
					return false;
				}

				const doc = editor.document;
				const lineNum = editor.selection.active.line;
				const line = doc.lineAt(lineNum);
				const text = line.text;
				const trimmed = text.trim();
				const insertCol = line.firstNonWhitespaceCharacterIndex;

				if (trimmed.startsWith(charcons.task.todo) || trimmed.startsWith(charcons.task.done)) {
					const start = new vscode.Position(lineNum, insertCol);
					const end = new vscode.Position(lineNum, insertCol + charcons.task.todo.length + 1);
					editor.edit(editBuilder => {
						editBuilder.delete(new vscode.Range(start, end));
					});
					return;
				}

				// Insert after indentation so we keep the original indentation
				const insertPos = new vscode.Position(lineNum, line.firstNonWhitespaceCharacterIndex);

				editor.edit(editBuilder => {
					editBuilder.insert(insertPos, `${charcons.task.todo} `);
				});
			} catch (error) {
				vscode.window.showErrorMessage(`Failed to mark as task: ${error.message}`);
				console.error('Mark as task error:', error);
			}
		}),

		toggleTaskState: vscode.commands.registerCommand(`${EXTENSION_NAME}.toggleTaskState`, function () {
			try {
				const editor = getDotodoEditorOrErrorMessage();

				if (!editor) {
					return false;
				}

				const doc = editor.document;
				const lineNum = editor.selection.active.line;
				const line = doc.lineAt(lineNum);
				const text = line.text;
				const leadingWhitespace = text.substring(0, line.firstNonWhitespaceCharacterIndex);
				const trimmed = text.trim();

				if (trimmed.startsWith(charcons.task.todo)) {
				// Mark current task as done and add timestamp
				const now = new Date();
				const timestamp = ` @${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`;
				const taskContent = trimmed.slice(charcons.task.todo.length + 1);
				const newTaskText = `${leadingWhitespace}${charcons.task.done} ${taskContent}${timestamp}`;
				
				editor.edit(editBuilder => {
					editBuilder.replace(line.range, newTaskText);
					
					// Find and mark all subtasks as done
					const currentIndentLevel = leadingWhitespace.length;
					
					// Look at all lines below the current task
					for (let i = lineNum + 1; i < doc.lineCount; i++) {
						const subtaskLine = doc.lineAt(i);
						const subtaskText = subtaskLine.text;
						const subtaskTrimmed = subtaskText.trim();
						
						// Stop if we reach an empty line or a line with same/less indentation that's not a task
						if (subtaskTrimmed === '') {
							continue;
						}
						
						const subtaskIndentLevel = subtaskText.substring(0, subtaskLine.firstNonWhitespaceCharacterIndex).length;
						
						// Stop if we encounter a line with same or less indentation
						if (subtaskIndentLevel <= currentIndentLevel) {
							break;
						}
						
						// If it's a subtask (more indented and is a task), mark it as done with timestamp
						if (subtaskTrimmed.startsWith(charcons.task.todo)) {
							const subtaskLeadingWhitespace = subtaskText.substring(0, subtaskLine.firstNonWhitespaceCharacterIndex);
							const subtaskContent = subtaskTrimmed.slice(charcons.task.todo.length + 1);
							const newSubtaskText = `${subtaskLeadingWhitespace}${charcons.task.done} ${subtaskContent}${timestamp}`;
							editBuilder.replace(subtaskLine.range, newSubtaskText);
						}
					}
				});
			} else if (trimmed.startsWith(charcons.task.done)) {
				// Mark current task as todo (undone) and remove timestamp
				let taskContent = trimmed.slice(charcons.task.done.length + 1);
				// Remove timestamp if present (format: @YYYY-MM-DD HH:mm:ss)
				taskContent = taskContent.replace(/ @\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/, '');
				const newTaskText = `${leadingWhitespace}${charcons.task.todo} ${taskContent}`;
				
				editor.edit(editBuilder => {
					editBuilder.replace(line.range, newTaskText);
					
					// Find and mark all subtasks as undone (todo)
					const currentIndentLevel = leadingWhitespace.length;
					
					// Look at all lines below the current task
					for (let i = lineNum + 1; i < doc.lineCount; i++) {
						const subtaskLine = doc.lineAt(i);
						const subtaskText = subtaskLine.text;
						const subtaskTrimmed = subtaskText.trim();
						
						// Stop if we reach an empty line or a line with same/less indentation that's not a task
						if (subtaskTrimmed === '') {
							continue;
						}
						
						const subtaskIndentLevel = subtaskText.substring(0, subtaskLine.firstNonWhitespaceCharacterIndex).length;
						
						// Stop if we encounter a line with same or less indentation
						if (subtaskIndentLevel <= currentIndentLevel) {
							break;
						}
						
						// If it's a subtask (more indented and is a task), mark it as undone and remove timestamp
						if (subtaskTrimmed.startsWith(charcons.task.done)) {
							const subtaskLeadingWhitespace = subtaskText.substring(0, subtaskLine.firstNonWhitespaceCharacterIndex);
							let subtaskContent = subtaskTrimmed.slice(charcons.task.done.length + 1);
							// Remove timestamp if present
							subtaskContent = subtaskContent.replace(/ @\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/, '');
							const newSubtaskText = `${subtaskLeadingWhitespace}${charcons.task.todo} ${subtaskContent}`;
							editBuilder.replace(subtaskLine.range, newSubtaskText);
						}
					}
				});
			}
			} catch (error) {
				vscode.window.showErrorMessage(`Failed to toggle task state: ${error.message}`);
				console.error('Toggle task state error:', error);
			}
		}),

		archiveDone: vscode.commands.registerCommand(`${EXTENSION_NAME}.archiveDone`, archiveDone),

		indentTask: vscode.commands.registerCommand(`${EXTENSION_NAME}.indentTask`, function () {
			try {
				const editor = getDotodoEditorOrErrorMessage();

				if (!editor) {
					return vscode.commands.executeCommand('default:type', { text: '\t' });
				}

				const selection = editor.selection;
			const startLine = selection.start.line;
			const endLine = selection.end.line;

			// Check if we have a multi-line selection
			if (startLine !== endLine) {
				// Multi-line selection: indent all task lines in the selection
				editor.edit(editBuilder => {
					for (let lineNum = startLine; lineNum <= endLine; lineNum++) {
						const line = editor.document.lineAt(lineNum);
						const text = line.text;
						const trimmed = text.trim();

						// Only indent lines that are tasks
						if (trimmed.startsWith(charcons.task.todo) || trimmed.startsWith(charcons.task.done)) {
							editBuilder.insert(new vscode.Position(lineNum, 0), '\t');
						}
					}
				}).then(() => {
					// Maintain the selection but adjust for the added tabs
					const newStart = new vscode.Position(startLine, selection.start.character + 1);
					const newEnd = new vscode.Position(endLine, selection.end.character + 1);
					editor.selection = new vscode.Selection(newStart, newEnd);
				});
			} else {
				// Single line: existing behavior
				const position = editor.selection.active;
				const lineNum = position.line;
				const line = editor.document.lineAt(lineNum);
				const text = line.text;
				const trimmed = text.trim();

				// Check if current line is a task
				if (trimmed.startsWith(charcons.task.todo) || trimmed.startsWith(charcons.task.done)) {
					// Add tab at the beginning of the line
					editor.edit(editBuilder => {
						editBuilder.insert(new vscode.Position(lineNum, 0), '\t');
					}).then(() => {
						// Maintain cursor position relative to the line content
						const newPosition = new vscode.Position(lineNum, position.character + 1);
						editor.selection = new vscode.Selection(newPosition, newPosition);
					});
				} else {
					// Default tab behavior for non-task lines
					return vscode.commands.executeCommand('default:type', { text: '\t' });
				}
			}
			} catch (error) {
				vscode.window.showErrorMessage(`Failed to indent task: ${error.message}`);
				console.error('Indent task error:', error);
			}
		}),
	};

	registerDecorations(context);

	// Track newly created empty tasks for double-enter cancellation and ESC cancellation
	let lastCreatedTaskInfo = null;

	function setNewEmptyTaskContext(value) {
		vscode.commands.executeCommand('setContext', 'dotodos.newEmptyTask', value);
	}

	// Auto-create task on Enter key
	const enterDisposable = vscode.commands.registerCommand(`${EXTENSION_NAME}.onEnter`, () => {
		const editor = vscode.window.activeTextEditor;
		if (!editor || editor.document.languageId !== LANG_ID) {
			return vscode.commands.executeCommand('default:type', { text: '\n' });
		}

		const position = editor.selection.active;
		const currentLine = editor.document.lineAt(position.line);
		const currentText = currentLine.text;
		const trimmed = currentText.trim();

		// Check for double-enter on empty task (cancel task creation)
		if (lastCreatedTaskInfo && 
			lastCreatedTaskInfo.line === position.line && 
			lastCreatedTaskInfo.text === currentText &&
			trimmed === charcons.task.todo) {
			// Remove the task checkbox and space, keep only indentation
			const indentation = currentText.substring(0, currentLine.firstNonWhitespaceCharacterIndex);
			editor.edit(editBuilder => {
				editBuilder.replace(currentLine.range, indentation);
			}).then(() => {
				// Insert newline after removing checkbox
				vscode.commands.executeCommand('default:type', { text: '\n' });
			});
			lastCreatedTaskInfo = null;
			setNewEmptyTaskContext(false);
			return;
		}

		// Check if current line is a task AND cursor is at the end of the line
		if ((trimmed.startsWith(charcons.task.todo) || trimmed.startsWith(charcons.task.done)) && 
			position.character === currentText.length) {
			// Get indentation of current line
			const indentation = currentText.substring(0, currentLine.firstNonWhitespaceCharacterIndex);
			const newTaskLine = `${indentation}${charcons.task.todo} `;
			
			// Insert new line with new task at the end of current line
			editor.edit(editBuilder => {
				editBuilder.insert(new vscode.Position(position.line, currentText.length), '\n' + newTaskLine);
			}).then(() => {
				// Position cursor at end of new task line
				const newPosition = new vscode.Position(position.line + 1, newTaskLine.length);
				editor.selection = new vscode.Selection(newPosition, newPosition);
				
				// Track this new task for potential double-enter/backspace/esc cancellation
				lastCreatedTaskInfo = {
					line: position.line + 1,
					text: newTaskLine
				};
				setNewEmptyTaskContext(true);
			});
		} else {
			// Default behavior for non-task lines or when cursor is not at end
			lastCreatedTaskInfo = null;
			setNewEmptyTaskContext(false);
			return vscode.commands.executeCommand('default:type', { text: '\n' });
		}
	});

	// Handle BACKSPACE key to cancel task creation
	const backspaceDisposable = vscode.commands.registerCommand(`${EXTENSION_NAME}.onBackspace`, () => {
		const editor = vscode.window.activeTextEditor;
		if (!editor || editor.document.languageId !== LANG_ID) {
			return vscode.commands.executeCommand('deleteLeft');
		}

		const position = editor.selection.active;
		const currentLine = editor.document.lineAt(position.line);
		const currentText = currentLine.text;
		const trimmed = currentText.trim();
		const indentation = currentText.substring(0, currentLine.firstNonWhitespaceCharacterIndex);

		// Check if cursor is right after the space following the checkbox (at the end of "☐ ")
		if (lastCreatedTaskInfo && 
			lastCreatedTaskInfo.line === position.line && 
			trimmed === charcons.task.todo &&
			position.character === indentation.length + charcons.task.todo.length + 1) {
			// Remove checkbox and space, keep indentation
			editor.edit(editBuilder => {
				editBuilder.replace(currentLine.range, indentation);
			}).then(() => {
				// Move cursor to end of indentation
				const newPosition = new vscode.Position(position.line, indentation.length);
				editor.selection = new vscode.Selection(newPosition, newPosition);
			});
			lastCreatedTaskInfo = null;
			setNewEmptyTaskContext(false);
		} else {
			// Default BACKSPACE behavior
			return vscode.commands.executeCommand('deleteLeft');
		}
	});

	// Handle ESC key to cancel task creation (remove checkbox, keep indentation and cursor)
	const escDisposable = vscode.commands.registerCommand(`${EXTENSION_NAME}.onEsc`, () => {
		const editor = vscode.window.activeTextEditor;
		if (!editor || editor.document.languageId !== LANG_ID) {
			return;
		}

		const position = editor.selection.active;
		const currentLine = editor.document.lineAt(position.line);
		const currentText = currentLine.text;
		const trimmed = currentText.trim();
		const indentation = currentText.substring(0, currentLine.firstNonWhitespaceCharacterIndex);

		// Only act if this is a tracked newly created empty task
		if (lastCreatedTaskInfo &&
			lastCreatedTaskInfo.line === position.line &&
			trimmed === charcons.task.todo) {
			// Remove checkbox and space, keep indentation, keep cursor in place
			editor.edit(editBuilder => {
				editBuilder.replace(currentLine.range, indentation);
			}).then(() => {
				const newPosition = new vscode.Position(position.line, indentation.length);
				editor.selection = new vscode.Selection(newPosition, newPosition);
			});
			lastCreatedTaskInfo = null;
			setNewEmptyTaskContext(false);
		}
	});

	context.subscriptions.push(enterDisposable, backspaceDisposable, escDisposable);

	// Without pushing to context.subscriptions, cleanup would not happen 
	// automatically, which can cause issues especially if the extension 
	// is enabled/disabled multiple times during a session.
	context.subscriptions.push(...Object.values(subscriptions));
	// context.subscriptions.push(commands.markAsTask);
}

// This method is called when your extension is deactivated
function deactivate() {}

function archiveDone() {
    try {
        const editor = getDotodoEditorOrErrorMessage();
        if (!editor) return;

        const doc = editor.document;
    const allLines = [];
    const doneTasksWithContent = [];
    const linesToSkip = new Set();

    // Helper function to check if line is a task
    function isTaskLine(trimmed) {
        return trimmed.startsWith(charcons.task.todo) || trimmed.startsWith(charcons.task.done);
    }

    // Helper function to check if line is a section
    function isSectionLine(lineText) {
        const trimmed = lineText.trim();
        if (!trimmed) return false;
        if (isTaskLine(trimmed)) return false;
        return SECTION_LINE_PATTERN.test(trimmed);
    }

    // Helper to get content lines for a task
    function getTaskContentLines(taskLineNum) {
        const contentLines = [];
        const taskLine = doc.lineAt(taskLineNum);
        const taskIndent = taskLine.text.substring(0, taskLine.firstNonWhitespaceCharacterIndex).length;

        for (let i = taskLineNum + 1; i < doc.lineCount; i++) {
            const line = doc.lineAt(i);
            const trimmed = line.text.trim();
            const lineIndent = line.text.substring(0, line.firstNonWhitespaceCharacterIndex).length;

            if (trimmed === '') {
                contentLines.push(i);
                continue;
            }

            if (isTaskLine(trimmed) && lineIndent <= taskIndent) {
                break;
            }

            if (isSectionLine(line.text)) {
                break;
            }

            if (isTaskLine(trimmed) && lineIndent > taskIndent) {
                break;
            }

            contentLines.push(i);
        }

        return contentLines;
    }

    // First pass: collect done tasks with their content
    for (let i = 0; i < doc.lineCount; i++) {
        if (linesToSkip.has(i)) continue;

        const line = doc.lineAt(i);
        const trimmed = line.text.trim();
        
        if (trimmed.startsWith(charcons.task.done)) {
            // Add the task line
            doneTasksWithContent.push(line.text);
            linesToSkip.add(i);

            // Get and add content lines
            const contentLines = getTaskContentLines(i);
            for (const contentLineNum of contentLines) {
                doneTasksWithContent.push(doc.lineAt(contentLineNum).text);
                linesToSkip.add(contentLineNum);
            }
        }
    }

    if (doneTasksWithContent.length === 0) {
        vscode.window.showInformationMessage('No done tasks to archive');
        return;
    }

    // Second pass: collect remaining lines
    for (let i = 0; i < doc.lineCount; i++) {
        if (!linesToSkip.has(i)) {
            allLines.push(doc.lineAt(i).text);
        }
    }

    // Check if Archived exists
    let hasArchived = false;
    for (let line of allLines) {
        if (line.trim().startsWith('Archived:')) {
            hasArchived = true;
            break;
        }
    }

    if (!hasArchived) {
        allLines.push('', 'Archived:');
    }

    // Add done tasks with their content
    allLines.push(...doneTasksWithContent);

    // Replace entire document
    const newText = allLines.join('\n');
    editor.edit(editBuilder => {
        editBuilder.replace(new vscode.Range(0, 0, doc.lineCount, 0), newText);
    });
    } catch (error) {
        vscode.window.showErrorMessage(`Failed to archive done tasks: ${error.message}`);
        console.error('Archive done error:', error);
    }
}

module.exports = {
	activate,
	deactivate
}
